class LocalIdentifierManager {
    private hashToLocal: Map<string, number> = new Map();
    private localToHash: Map<number, string> = new Map();
    private nextId: number = 1;

    // 持久化存储接口
    private storage: {
        save(): Promise<void>;
        load(): Promise<void>;
    };

    constructor(storage: any) {
        this.storage = storage;
