    // 获取或创建本地标识符
    getOrCreateLocalId(hash: string): number {
        let localId = this.hashToLocal.get(hash);
        if (!localId) {
            localId = this.nextId++;
            this.hashToLocal.set(hash, localId);
            this.localToHash.set(localId, hash);
        }
        return localId;
    }

    // 获取哈希值
    getHash(localId: number): string | undefined {
        return this.localToHash.get(localId);
    }

    // 批量预加载哈希映射
    async batchPreload(hashes: string[]): Promise<void> {
