fn advance(cwd: &Path, module: &str) -> Output {
    placement(cwd, &["advance", "--module-cid", module], None)
}

fn stage(cwd: &Path, receipt: &str, key: &Path, primary: &str) -> Output {
    placement(
        cwd,
        &[
            "canary-stage-from-distributed-receipt",
            "--receipt-cid",
            receipt,
            "--candidate-basis-points",
            "5000",
            "--expected-primary-head",
            primary,
        ],
        Some(key),
    )
}

fn promote(cwd: &Path, receipt: &str, key: &Path, primary: &str, canary: &str) -> Output {
    placement(
        cwd,
        &[
            "canary-advance-from-distributed-receipt",
            "--receipt-cid",
            receipt,
            "--expected-primary-head",
            primary,
            "--expected-canary-head",
            canary,
        ],
        Some(key),
    )
}

fn placement(cwd: &Path, command: &[&str], key: Option<&Path>) -> Output {
    let mut args: Vec<&OsStr> = ["program", "module", "foreign-process", "placement"]
        .iter()
        .map(OsStr::new)
        .collect();
    args.extend(command.iter().map(OsStr::new));
    if let Some(key) = key {
        args.extend([OsStr::new("--auth-key"), key.as_os_str()]);
    }
    args.extend(
        ["--slot", SLOT, "--node-id", NODE, "--format", "json"]
            .iter()
            .map(OsStr::new),
    );
    run(cwd, args)
}

