use std::path::Path;

use unicodex_core::{decode_node, encode_value_node, Node, ObjectStore, Value};

pub fn forge_second_output(cwd: &Path, suite: &str) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(suite).unwrap()).unwrap()
    else {
        panic!("benchmark suite must be a Value map")
    };
    let Value::List(cases) = field_mut(&mut entries, "cases") else {
        panic!("benchmark suite cases must be a list")
    };
    let Value::Map(first) = &cases[0] else {
        panic!("benchmark suite case must be a map")
    };
    let replacement = field(first, "output").clone();
    let Value::Map(second) = &mut cases[1] else {
        panic!("benchmark suite case must be a map")
    };
    field_mut(second, "output").clone_from(&replacement);
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

fn field<'a>(entries: &'a [(Value, Value)], name: &str) -> &'a Value {
    &entries
        .iter()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1
}

fn field_mut<'a>(entries: &'a mut [(Value, Value)], name: &str) -> &'a mut Value {
    &mut entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1
}

